import copy

def f_correct(grid):
    g = copy.deepcopy(grid)

    # Find vertical 5-line column
    vcol = None
    for c in range(len(g[0])):
        count = sum(1 for r in range(len(g)) if g[r][c] == 5)
        if count >= 2:
            vcol = c
            break

    if vcol is None:
        return g

    # Find FIRST row that has content next to the 5-line
    # Content = any column > 0 with value != 0 (excluding the 5-column itself)
    content_row = None
    for r in range(len(g)):
        for c in range(len(g[0])):
            if c != vcol and g[r][c] > 0:
                content_row = r
                break
        if content_row:
            break

    if content_row is None:
        return g

    # Get the horizontal slice from content_row (all cols from first non-zero to end before zeros)
    hleft = len(g[0])
    hright = -1
    for c in range(len(g[0])):
        if g[content_row][c] > 0 and c != vcol:
            hleft = min(hleft, c)
            hright = max(hright, c)

    print(f"vcol={vcol}, content_row={content_row}, hleft={hleft}, hright={hright}")
    print(f"Content row values {g[content_row][hleft:hright+1]}")

    # Copy this pattern to all other rows that have a 5 in vcol
    for r in range(len(g)):
        if g[r][vcol] == 5 and r != content_row:
            for c in range(hleft, hright + 1):
                g[r][c] = g[content_row][c]

    return g

