import copy

def f_both_sides(grid):
    g = copy.deepcopy(grid)

    # Find vertical 5-line
    vcol = None
    for c in range(len(g[0])):
        count = sum(1 for r in range(len(g)) if g[r][c] == 5)
        if count >= 2:
            vcol = c
            break

    if vcol is None:
        return g

    # For LEFT side: collect values from rows that have content on the left
    # Use BOTTOMMOST row's left pattern
    left_content = []
    for r in range(len(g)-1, -1, -1):
        for c in range(vcol-1, -1, -1):
            if g[r][c] > 0 and g[r][c] != 5:
                left_content.append(g[r][c])
                break
        if left_content:
            break

    print(f"left_content={left_content}")

    # For RIGHT side: collect values from rows that have content on the right  
    # Use BOTTOMMOST row's right pattern
    right_pattern = []
    for r in range(len(g)):
        for c in range(vcol+1, len(g[0])):
            if g[r][c] > 0:
                right_pattern.extend([g[r][c]])
            elif g[r][c] == 5:
                continue
        if right_pattern:
            break

    print(f"right_pattern={right_pattern}")

    # Apply left pattern to all rows with 5s
    if left_content:
        for r in range(len(g)):
            if g[r][vcol] == 5:
                first_non_5 = False
                for c in range(vcol-1, -1, -1):
                    if not first_non_5:
                        g[r][c] = left_content[-1]
                        first_non_5 = True

    # Apply right pattern to all rows with 5s
    if right_pattern:
        for r in range(len(g)):
            if g[r][vcol] == 5:
                for i, val in enumerate(right_pattern):
                    nc = vcol + 1 + i
                    if nc < len(g[0]):
                        g[r][nc] = val

    return g

