import copy

def f_fixed(grid):
    g = copy.deepcopy(grid)

    # Find vertical 5-line
    vcol = None
    for c in range(len(g[0])):
        count = sum(1 for r in range(len(g)) if g[r][c] == 5)
        if count >= 2:
            vcol = c
            break

    if vcol is None:
        return g

    # Get LEFT pattern from bottommost row with content on left
    left_row = None
    for r in range(len(g)-1, -1, -1):
        for c in range(vcol-1, -1, -1):
            if g[r][c] > 0 and g[r][c] != 5:
                left_row = (r, c)
                break
        if left_row:
            break

    # Get RIGHT pattern from bottommost row with content on right
    right_row = None
    for r in range(len(g)):
        for c in range(vcol+1, len(g[0])):
            if g[r][c] > 0:
                right_row = (r, c)
                break
        if right_row:
            break

    print(f"left_row={left_row}, right_row={right_row}")

    # If there's a right pattern, apply it to all rows with 5s
    # Use full horizontal extent from bottommost row
    hstart = len(g[0])
    hend = -1
    if right_row:
        for c in range(right_row[0]):  # Scan this row
            if g[right_row[0]][c] > 0:
                hstart = min(hstart, c)
        for c in range(len(g[0])):
            if g[right_row[0]][c] > 0:
                hend = max(hend, c)

    if right_row and hstart <= hend:
        print(f"Applying right pattern {g[right_row[0]][hstart:hend+1]}")
        for r in range(len(g)):
            if g[r][vcol] == 5:
                for c in range(hstart, hend + 1):
                    g[r][c] = g[right_row[0]][c]

    # Similarly for left
    if left_row:
        hstart = len(g[0])
        hend = -1
        for c in range(left_row[0], -1, -1):
            if g[left_row[0]][c] > 0:
                hstart = min(hstart, c)
        for c in range(left_row[0]+1):
            if g[left_row[0]][c] > 0:
                hend = max(hend, c)

        if left_row and hstart <= hend:
            print(f"Applying left pattern {g[left_row[0]][hstart:hend+1]}")
            for r in range(len(g)):
                if g[r][vcol] == 5:
                    for c in range(hstart, hend + 1):
                        g[r][c] = g[left_row[0]][c]

    return g

