    for r in range(len(orig)):
        for c in range(vcol+1, len(orig[0])):
            if orig[r][c] > 0:
                right_row = (r, c)
                break
        if right_row:
            break

    print(f"left_row={left_row}, right_row={right_row}")

    def apply_pattern(pattern_row, vcol, direction='right'):
        hstart = len(orig[0])
        hend = -1
        for c in range(len(orig[0])):
            if c != vcol and orig[pattern_row[0]][c] > 0:
                hstart = min(hstart, c)
                hend = max(hend, c)

        if hstart <= hend:
            print(f"Applying {direction} pattern {orig[pattern_row[0]][hstart:hend+1]}")
            for r in range(len(g)):
                if g[r][vcol] == 5:
                    for c in range(hstart, hend + 1):
