        if count >= 2:
            vcols.append(c)

    if not vcols:
        return g

    vcol = vcols[0]

    # Get BOTTOMMOST row with content on left side (before first vcol)
    left_row = None
    for r in range(len(orig)-1, -1, -1):
        for c in range(vcol-1, -1, -1):
            if orig[r][c] > 0 and orig[r][c] != 5:
                left_row = (r, c)
                break
        if left_row:
            break

