    right_row = None
    for r in range(len(orig)-1, -1, -1):
        for c in range(vcol+1, len(orig[0])):
            if orig[r][c] > 0:
                right_row = (r, c)
                break
        if right_row:
            break

    def apply_pattern(src_row, vcol, hstart, hend):
        if src_row is None:
            return
        pattern = list(orig[src_row[0]][hstart:hend+1])

        for r in range(len(g)):
            if g[r][vcol] == 5:
                has_some_content = any(g[r][c] > 0 and g[r][c] != 5 
                                      for c in range(hstart, hend+1))

                if not has_some_content:
                    for c_idx, val in enumerate(pattern):
                        target_c = hstart + c_idx
                        if orig[r][target_c] == 0:
                            g[r][target_c] = val

    if left_row:
        hstart = len(orig[0])
        hend = -1
        for c in range(len(orig[0])):
            if c != vcol and orig[left_row[0]][c] > 0:
                hstart = min(hstart, c)
                hend = max(hend, c)
        apply_pattern(left_row, vcol, hstart, hend)

    if right_row:
        hstart = len(orig[0])
        hend = -1
        for c in range(len(orig[0])):
            if c != vcol and orig[right_row[0]][c] > 0:
                hstart = min(hstart, c)
