import copy

def f_propagate_horiz(grid):
    """For each 5-cell, horizontally propagate the content found in that direction."""
    orig = copy.deepcopy(grid)
    g = copy.deepcopy(grid)

    vcols = []
    for c in range(len(orig[0])):
        count = sum(1 for r in range(len(orig)) if orig[r][c] == 5)
        if count >= 2:
            vcols.append(c)

    if not vcols:
        return g

    # For each cell with a 5, find and propagate content in both directions
    for r in range(len(g)):
        for c in range(len(g[0])):
            if g[r][c] == 5:
                # Look for non-zero/non-5 content to the LEFT and RIGHT
                left_pattern = []
                right_pattern = []

                # Scan left
                for dc in range(1, c+1):
                    nc = c - dc
                    if g[r][nc] > 0:
                        left_pattern.insert(0, g[r][nc])
                    elif g[r][nc] == 0:
                        break

                # Scan right  
                for dc in range(1, len(g[0])-c):
                    nc = c + dc
                    if g[r][nc] > 0:
                        right_pattern.append(g[r][nc])
                    elif g[r][nc] == 0:
                        break

                # Now propagate these patterns vertically to all other 5-cells in the same row... 
                # Actually, let me try propagating to OTHER rows instead
                pass

    # New approach: For each column that has BOTH a 5 AND some adjacent non-zero non-5 content,
    # copy that content to all rows with 5s in that column
    for c in range(len(g[0])):
        has_5_col = any(g[r][c] == 5 for r in range(len(g)))

        # Check if column c has nearby content (not itself being a 5-col)
        nearby_content = []
        for r in range(len(g)):
            if c != 0 and g[r][c-1] > 0 and g[r][c-1] != 5:
                nearby_content.append((r, 'left', g[r][c-1]))
            elif c < len(g[0])-1 and g[r][c+1] > 0:
                nearby_content.append((r, 'right', g[r][c+1]))

        if nearby_content:
            print(f"Column {c} has nearby content: {nearby_content}")

            # Copy nearest non-5 content from rows with 5s to other 5-positions
            for nr, ndir, nv in nearby_content:
                if has_5_col:
                    for tr in range(len(g)):
                        if g[tr][c] == 5 and g[tr][nr] == 0 and orig[tr][c] == 0:
                            g[tr][c] = nv

    return g

