    for vcol, rows_with_5 in vcols:
        rows_with_content = [r for r in range(len(grid)) 
                            if any(grid[r][c] != 0 for c in range(vcol + 1, 10))]
        if not rows_with_content:
            continue

        source_row = max(rows_with_content)  # Bottommost
        pattern_start = vcol + 1
        pattern = list(grid[source_row][pattern_start:])

        for r in rows_with_5:
            for idx, val in enumerate(pattern):
                target_col = pattern_start + idx
                out[r][target_col] = val

    return out

result = solve(test_in)
print("Solution:")
for i, row in enumerate(result):
    print(f"Row {i}: {row}")

print("\nSubmitting:")
{"action": "submit", "grid": result}
